ns/","statut_verification":"source_confirmee","date_verification":"2026-11-22","source_verification":"https://www.reunionbenevolat.re/associations/","score_priorite":78,"periode_validite":"Source consultée en novembre 2026. Existence de la structure documentée ; ouverture des permanences, accès, règles et montants doivent être vérifiés."},{"nom":"Fonds départemental d''aide aux jeunes — informations Département 974","categorie":"jeunesse","commune":null,"organisme":"Département de La Réunion","type_dispositif":"orientation","zone_couverte":"La Réunion","description_fr":"Le Département présente le Fonds départemental d''aide aux jeunes dans ses dispositifs d''insertion. Les plafonds, les publics éligibles, les montants et la campagne actuelle doivent être confirmés par le service social ou la Mission locale.","demarches_fr":"Se renseigner auprès du Département et de la Mission locale pour connaître le règlement, les pièces justificatives et les périodes de dépôt en vigueur.","lien_officiel":"https://www.departement974.fr/actualite/revel-out-talent-2025","statut_verification":"a_reconfirmer","date_verification":"2026-11-22","source_verification":"https://www.departement974.fr/actualite/revel-out-talent-2025","score_priorite":82,"periode_validite":"Source consultée en novembre 2026. Existence de la structure documentée ; ouverture des permanences, accès, règles et montants doivent être vérifiés."}]'::jsonb) AS x(
      nom text,categorie text,commune text,organisme text,type_dispositif text,zone_couverte text,
      description_fr text,demarches_fr text,lien_officiel text,statut_verification text,
      date_verification date,source_verification text,score_priorite integer,periode_validite text)
  LOOP
    IF NOT EXISTS (SELECT 1 FROM public.aides_reunion a WHERE lower(btrim(a.nom))=lower(btrim(r.nom))) THEN
      INSERT INTO public.aides_reunion (
        nom,categorie,commune,organisme,type_dispositif,zone_couverte,description,
        description_fr,description_kreol,demarches_fr,demarches_kreol,lien,lien_officiel,
        source_verification,statut_verification,date_verification,score_priorite,
