    lien_officiel='https://www.caf.fr/allocataires/caf-de-la-reunion/offre-de-service/accident-de-vie/les-points-conseil-budget',
    source_verification='https://www.caf.fr/allocataires/caf-de-la-reunion/offre-de-service/accident-de-vie/les-points-conseil-budget',
    type_dispositif='service_gratuit', organisme='Points Conseil Budget labellisés (réseau de La Réunion)',
